#include <iostream>
#include <string>
#include <sstream>
#include <cmath>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    int n;
    double p;
    iss >> n >> p;
    int x = 0;
    while (probability(x, n) < p) {
        x++;
    }
    std::cout << x << std::endl;
    return 0;
}

double probability(int x, int n) {
    if (n < 3 || x < 0 || x > n) return 0.0; // safeguard against invalid inputs
    double term1 = 1.5 * x / n * (n - x) / (n - 1) * (n - x - 1) / (n - 2);
    double term2 = 3.0 * x / n * (x - 1) / (n - 1) * (n - x) / (n - 2);
    double term3 = 1.0 * x / n * (x - 1) / (n - 1) * (x - 2) / (n - 2);
    return term1 + term2 + term3;
}

